package cn.tsign.hz.sdk_run;

import cn.tsign.hz.sdk_constant.ConfigConstant;
import cn.tsign.hz.sdk_core.ClientHelper;
import cn.tsign.hz.sdk_core.FileHelper;
import cn.tsign.hz.sdk_core.SignHelper;
import cn.tsign.hz.exception.DefineException;
import com.timevale.esign.paas.tech.bean.bean.PosBean;
import com.timevale.esign.paas.tech.bean.request.PlatformSignParam;
import com.timevale.esign.paas.tech.bean.request.SignFilePdfParam;
import com.timevale.esign.paas.tech.client.ServiceClient;
import com.timevale.esign.paas.tech.enums.SignType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.File;
import java.util.ArrayList;
import java.util.List;


/***
 * description: 平台自身签
 */

public class RunPlatformSign {

    private static final Logger LOGGER = LoggerFactory.getLogger(RunPlatformSign.class);
    private static SignHelper signHelper;

    static {
        try {
            if (true) {
                //1、注册客户端，全局使用，只需注册一次
                ClientHelper.registClient();
            }

            //2、获取已初始化的客户端，以便后续正常调用SDK提供的各种服务，全局使用，只需获取一次
            ServiceClient serviceClient = ClientHelper.getServiceClient(ConfigConstant.PROJECT_ID);

            //3、实例化辅助类
            signHelper = new SignHelper(serviceClient);
        } catch (DefineException e) {
            e.getE().printStackTrace();
        }
    }

//--------------------------------公有方法 start-------------------------------------

    public static void main(String[] args) throws DefineException {

        switch (0) {
            case 0:
                LOGGER.info("====>场景演示：平台自身自动落章（文件路径方式）<=====");
                platformSignByPdfFile();
                break;
            case 1:
                LOGGER.info("====>场景演示：平台自身自动落章（文件流方式）<=====");
                platformSignByPdfStream();
                break;
            case 2:
                LOGGER.info("====>场景演示：平台自身批量文件自动落章（文件路径方式）<=====");
                platformSignByBatchPdfFile();
                break;
            default:
                LOGGER.info("====>请选择应用场景<=====");
                break;
        }
    }
//--------------------------------公有方法 end---------------------------------------

//--------------------------------私有方法 start-------------------------------------

    // 当前程序所在文件目录
    private static final String ROOT_FOLDER = new File("").getAbsolutePath();
    //文件地址前缀拼接（可根据实际场景自定义）
    private static final String PATH_PREFEX = ROOT_FOLDER + File.separator + "pdf" + File.separator;

    /**
     * 文件路径方式平台自身自动落章
     */
    private static void platformSignByPdfFile() throws DefineException {
        /**
         * 平台自身PDF文件路径签署
         */
        // 签署文件信息
        SignFilePdfParam file = new SignFilePdfParam();
        file.setSrcPdfFile(PATH_PREFEX + "test.pdf");// 待签署PDF文件本地路径，含文件名（与bytes至少有一个不为空）
        file.setDstPdfFile(PATH_PREFEX + "Signed_Platform.pdf");// 签署后PDF文件本地路径，含文件名（为空时返回签署后的文件流）
        file.setFileName("我的平台自身签署文件.pdf");

        // 签章位置信息
        List<PosBean> posBeans = new ArrayList<>();
        PosBean signPos = new PosBean();
        signPos.setPosPage("1");// 签署页码（除关键字签章外，页码均不可为空）若为多页签章，支持指定多个页码，例如格式：“1-3,5,8“
        signPos.setPosX(150);// 签署位置X坐标，若为关键字定位，相对于关键字的X坐标偏移量，默认0
        signPos.setPosY(0);// 签署位置Y坐标，若为关键字定位，相对于关键字的Y坐标偏移量，默认0
        signPos.setKeyWord("甲方盖章");// 关键字，仅限关键字签章时有效，若为关键字定位时，不可空
        signPos.setWidth(159);// 印章展现宽度，将以此宽度对印章图片做同比缩放。
        signPos.setAddSignTime(true);// 是否显示本地签署时间，需要width设置92以上才可以看到时间
        posBeans.add(signPos);

        //印章数据二选一传入
        //印章Base64数据
        String sealData = "";
        //String sealId = "985ec1e1-1111-0000-2222-123456789";//印章也可以直接传入平台在e签宝官网的印章编号

        //传入企业用户签署参数内
        PlatformSignParam platformSignParam = new PlatformSignParam();
        platformSignParam.setSealData(sealData);//印章Base64
        //platformSignParam.setSealId(sealId);//印章ID数据
        platformSignParam.setPosBeans(posBeans);//签章位置信息
        platformSignParam.setSignType(SignType.Key);//签章类型：Single，单页签章； Multi，多页签章； Edges，签骑缝章； Key，关键字签章
        platformSignParam.setFileBean(file);//签署文件信息
        signHelper.platformSign(platformSignParam);

    }


    /**
     * 文件流方式平台自身自动落章
     */
    private static void platformSignByPdfStream() throws DefineException {

        /**
         * 平台自身PDF文件流签署
         */
        // 签署文件信息
        SignFilePdfParam file = new SignFilePdfParam();
        //PDF文件信息
        String srcPdfPath = PATH_PREFEX + "test.pdf";
        //获取PDF文件的字节流
        byte[] srcPdfBytes = FileHelper.getFileBytes(srcPdfPath);
        file.setStreamFile(srcPdfBytes);// 待填充PDF文件本地二进制数据
        file.setFileName("我的平台自身签署文件.pdf");
        //file.setDstPdfFile(PATH_PREFEX + "Signed_Platform.pdf");// 签署后PDF文件本地路径，含文件名（为空时返回签署后的文件流）

        // 签章位置信息
        List<PosBean> posBeans = new ArrayList<>();
        PosBean signPos = new PosBean();
        signPos.setPosPage("1");// 签署页码（除关键字签章外，页码均不可为空）若为多页签章，支持指定多个页码，例如格式：“1-3,5,8“
        signPos.setPosX(150);// 签署位置X坐标，若为关键字定位，相对于关键字的X坐标偏移量，默认0
        signPos.setPosY(0);// 签署位置Y坐标，若为关键字定位，相对于关键字的Y坐标偏移量，默认0
        signPos.setKeyWord("甲方盖章");// 关键字，仅限关键字签章时有效，若为关键字定位时，不可空
        signPos.setWidth(159);// 印章展现宽度，将以此宽度对印章图片做同比缩放。
        signPos.setAddSignTime(true);// 是否显示本地签署时间，需要width设置92以上才可以看到时间
        posBeans.add(signPos);

        //印章数据二选一传入
        //印章Base64数据，需要和调用方企业（应用ID所属的企业）对应的主体名称一致
        String sealData = "";
        //String sealId = "985ec1e1-1111-0000-2222-123456789"//印章也可以直接传入平台在e签宝官网的印章编号

        //传入平台自身签署参数内
        PlatformSignParam platformSignParam = new PlatformSignParam();
        platformSignParam.setSealData(sealData);//印章Base64
        //platformSignParam.setSealId(sealId);//印章ID数据
        platformSignParam.setPosBeans(posBeans);//签章位置信息
        platformSignParam.setSignType(SignType.Key);//签章类型：Single，单页签章； Multi，多页签章； Edges，签骑缝章； Key，关键字签章
        platformSignParam.setFileBean(file);//签署文件信息
        signHelper.platformSign(platformSignParam);
    }



    /**
     * 文件路径方式平台自身批量文件自动落章
     */
    private static void platformSignByBatchPdfFile() throws DefineException {
        // 签署文件A信息
        SignFilePdfParam fileA = new SignFilePdfParam();
        fileA.setSrcPdfFile(PATH_PREFEX + "test.pdf");// 待签署PDF文件本地路径，含文件名（与bytes至少有一个不为空）
        fileA.setDstPdfFile(PATH_PREFEX + "Signed_PlatformA.pdf");// 签署后PDF文件本地路径，含文件名（为空时返回签署后的文件流）
        fileA.setFileName("平台自身签署文件A.pdf");
        fileA.setFileNo("文件标识AAAAAAAA");

        // 签署文件B信息
        SignFilePdfParam fileB = new SignFilePdfParam();
        fileB.setSrcPdfFile(PATH_PREFEX + "授权.pdf");// 待签署PDF文件本地路径，含文件名（与bytes至少有一个不为空）
        fileB.setDstPdfFile(PATH_PREFEX + "Signed_PlatformB.pdf");// 签署后PDF文件本地路径，含文件名（为空时返回签署后的文件流）
        fileB.setFileName("平台自身签署文件B.pdf");
        fileB.setFileNo("文件标识BBBBBBBBB");


        // 签章位置信息
        List<PosBean> posBeans = new ArrayList<>();
        PosBean signPos = new PosBean();
        signPos.setPosPage("1");// 签署页码（除关键字签章外，页码均不可为空）若为多页签章，支持指定多个页码，例如格式：“1-3,5,8“
        signPos.setPosX(100);// 签署位置X坐标，若为关键字定位，相对于关键字的X坐标偏移量，默认0
        signPos.setPosY(20);// 签署位置Y坐标，若为关键字定位，相对于关键字的Y坐标偏移量，默认0
        signPos.setKeyWord("甲方盖章");// 关键字，仅限关键字签章时有效，若为关键字定位时，不可空
        //signPos.setWidth(96);// 印章展现宽度，将以此宽度对印章图片做同比缩放。
        signPos.setAddSignTime(true);// 是否显示本地签署时间，需要width设置92以上才可以看到时间
        posBeans.add(signPos);

        //印章二选一传入
        //印章Base64数据
        //String sealData = "";
        //印章也可以直接传入平台在e签宝官网的印章编号
        String sealId = "b077c906-f4e5-111e-8f05-1535cd5b7fcb";

        //构造平台自身签署文件数组
        PlatformSignParam platformSignParamA = new PlatformSignParam();
        //platformSignParamA.setSealData(sealData);//印章Base64数据
        platformSignParamA.setSealId(sealId);//印章ID数据
        platformSignParamA.setPosBeans(posBeans);//签章位置信息
        platformSignParamA.setSignType(SignType.Key);//签章类型：Single，单页签章； Multi，多页签章； Edges，签骑缝章； Key，关键字签章
        platformSignParamA.setFileBean(fileA);//签署文件A信息
        //platformSignParamA.setSealSpec(SealSpecEnum.IMAGE);

        PlatformSignParam platformSignParamB= new PlatformSignParam();
        //platformSignParamB.setSealData(sealData);//印章Base64数据
        platformSignParamB.setSealId(sealId);//印章ID数据
        platformSignParamB.setPosBeans(posBeans);//签章位置信息
        platformSignParamB.setSignType(SignType.Key);//签章类型：Single，单页签章； Multi，多页签章； Edges，签骑缝章； Key，关键字签章
        platformSignParamB.setFileBean(fileB);//签署文件B信息
        //batchBaseSignParamB.setSealSpec(SealSpecEnum.IMAGE);

        List<PlatformSignParam> signInfoParams = new ArrayList<>();
        signInfoParams.add(platformSignParamA);
        signInfoParams.add(platformSignParamB);
        signHelper.platformBatchSign(signInfoParams);

    }
//--------------------------------私有方法 end---------------------------------------
}

